-- N&A Beauty — DATOS DE PRUEBA (no son datos reales)
-- Catálogo de muestra + ~4 meses de ventas y entradas inventadas.
-- Las fechas son relativas al día en que se importa este archivo,
-- así los reportes de hoy / semana / mes siempre tienen datos.
--
-- USUARIOS DE PRUEBA (en producción los crea el POS):
--   nataly / NAbeauty-Admin-2026   → todos los permisos web
--   socio  / NAbeauty-Socio-2026   → ver reportes y descargar (no edita)
-- Cámbialos o bórralos antes de publicar el sistema.
-- ══════════════════════════════════════════════════════════════
USE nabeauty;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM inventario_movimientos;
DELETE FROM entrada_detalle;
DELETE FROM entradas;
DELETE FROM venta_detalle;
DELETE FROM ventas;
DELETE FROM producto_variantes;
DELETE FROM producto_imagenes;
DELETE FROM productos;
DELETE FROM categorias;
DELETE FROM usuario_permisos;
DELETE FROM usuarios;
DELETE FROM login_intentos;
SET FOREIGN_KEY_CHECKS = 1;






